public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) {
        return result;
    }
    int n = nums.length;
    if (n == 0) {
        return result;
    }
    // Heap's algorithm requires a copy to avoid modifying the original array
    int[] arr = nums.clone();
    int[] c = new int[n];
    // add the first permutation
    List<Integer> first = new ArrayList<>(n);
    for (int val : arr) {
        first.add(val);
    }
    result.add(first);
    int i = 0;
    while (i < n) {
        if (c[i] < i) {
            if (i % 2 == 0) {
                int temp = arr[0];
                arr[0] = arr[i];
                arr[i] = temp;
            } else {
                int temp = arr[c[i]];
                arr[c[i]] = arr[i];
                arr[i] = temp;
            }
            List<Integer> perm = new ArrayList<>(n);
            for (int val : arr) {
                perm.add(val);
            }
            result.add(perm);
            c[i]++;
            i = 0;
        } else {
            c[i] = 0;
            i++;
        }
    }
    return result;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to minimize candidate substrings
    String shortest = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        if (s.length() < minLen) {
            minLen = s.length();
            shortest = s;
        }
    }
    if (minLen == 0) {
        return 0;
    }

    int left = 1;
    int right = minLen;
    int best = 0;

    while (left <= right) {
        int mid = (left + right) >>> 1;
        boolean found = false;
        // Enumerate all substrings of length mid from the shortest string
        for (int i = 0; i + mid <= shortest.length(); i++) {
            String sub = shortest.substring(i, i + mid);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String other : strings) {
                if (other == null) {
                    ok = false;
                    break;
                }
                if (other.indexOf(sub) >= 0 || other.indexOf(rev) >= 0) {
                    continue;
                } else {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                found = true;
                break;
            }
        }
        if (found) {
            best = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return best;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    try {
        // Filter out null strings
        List<String> nonNullStrings = new ArrayList<>();
        for (String s : strings) {
            if (s != null) {
                nonNullStrings.add(s);
            }
        }
        if (nonNullStrings.isEmpty()) {
            return 0;
        }

        // Use first non-empty string as the basis for candidate substrings
        String base = null;
        for (String s : nonNullStrings) {
            if (!s.isEmpty()) {
                base = s;
                break;
            }
        }
        if (base == null) {
            return 0; // all strings empty
        }

        Set<String> processed = new HashSet<>();
        int maxLen = 0;
        int baseLen = base.length();

        for (int i = 0; i < baseLen; i++) {
            for (int j = i + 1; j <= baseLen; j++) {
                String candidate = base.substring(i, j);
                if (processed.contains(candidate)) {
                    continue;
                }
                processed.add(candidate);
                String rev = new StringBuilder(candidate).reverse().toString();

                boolean ok = true;
                for (String s : nonNullStrings) {
                    if (s.isEmpty()) {
                        ok = false;
                        break;
                    }
                    if (!s.contains(candidate) && !s.contains(rev)) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    maxLen = Math.max(maxLen, candidate.length());
                }
            }
        }
        return maxLen;
    } catch (Exception e) {
        // In case of any unexpected runtime error, return 0
        return 0;
    }
}

public int findLargestSubstring(java.util.List<String> strings) {
    // Handle null or empty input
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the longest string among the input list
    int maxLen = 0;
    for (String str : strings) {
        if (str == null) continue; // Skip null strings
        if (str.length() > maxLen) {
            maxLen = str.length();
        }
    }
    if (maxLen == 0) {
        return 0;
    }

    // Use the first non-null string as reference
    String reference = null;
    for (String str : strings) {
        if (str != null && str.length() > 0) {
            reference = str;
            break;
        }
    }
    if (reference == null) {
        return 0;
    }

    // Iterate over possible lengths from largest to smallest
    for (int len = maxLen; len >= 1; len--) {
        // Generate all substrings of 'reference' with this length
        int refLen = reference.length();
        for (int start = 0; start + len <= refLen; start++) {
            String candidate = reference.substring(start, start + len);
            String candidateRev = new StringBuilder(candidate).reverse().toString();

            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    ok = false;
                    break;
                }
                if (!(s.contains(candidate) || s.contains(candidateRev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }

    return 0; // No common substring found
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Treat null strings as empty strings for robustness
    List<String> safeStrings = new java.util.ArrayList<>(strings.size());
    for (String s : strings) {
        safeStrings.add(s == null ? "" : s);
    }
    String base = safeStrings.get(0);
    int baseLen = base.length();
    if (baseLen == 0) {
        return 0;
    }
    // Precompute reversed versions for quick reuse
    for (int len = baseLen; len >= 1; len--) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int start = 0; start + len <= baseLen; start++) {
            String candidate = base.substring(start, start + len);
            if (!seen.add(candidate)) {
                continue; // Skip duplicate substrings of same length
            }
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean allMatch = true;
            for (String s : safeStrings) {
                if (!(s.contains(candidate) || s.contains(rev))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
