    }
    Set<String> common = null;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        Set<String> curr = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                String sub = s.substring(i, j);
                curr.add(sub);
                curr.add(new StringBuilder(sub).reverse().toString());
            }
        }
        if (common == null) {
            common = curr;
        } else {
            common.retainAll(curr);
            if (common.isEmpty()) {
                return 0;
            }
        }
    }
    if (common == null || common.isEmpty()) {
        return 0;
    }
    int maxLen = 0;
    for (String str : common) {
        int l = str.length();
        if (l > maxLen) {
            maxLen = l;
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;
    // 8-direction deltas
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                depositCount++;
                // iterative DFS using stack
                int[] stackR = new int[rows * cols];
                int[] stackC = new int[rows * cols];
                int top = 0;
                stackR[0] = r;
                stackC[0] = c;
                visited[r][c] = true;
                while (top >= 0) {
                    int cr = stackR[top];
                    int cc = stackC[top];
                    top--;
                    for (int dir = 0; dir < 8; dir++) {
                        int nr = cr + dr[dir];
                        int nc = cc + dc[dir];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            top++;
                            stackR[top] = nr;
                            stackC[top] = nc;
                        }
                    }
                }
            }
        }
    }
    return depositCount;
}

