            visited[i] = null;
            continue;
        }
        visited[i] = new boolean[grid[i].length];
    }

    int count = 0;
    java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            continue;
        }
        int cols = grid[r].length;
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] != '@' || visited[r][c]) {
                continue;
            }
            count++;
            visited[r][c] = true;
            stack.push(new int[]{r, c});

            while (!stack.isEmpty()) {
                int[] cell = stack.pop();
                int curR = cell[0];
                int curC = cell[1];

                // Up
                if (curR > 0) {
                    int neR = curR - 1;
                    int neC = curC;
                    if (grid[neR] != null
                        && grid[neR].length > neC
                        && grid[neR][neC] == '@'
                        && !visited[neR][neC]) {
                        visited[neR][neC] = true;
                        stack.push(new int[]{neR, neC});
                    }
                }
                // Down
                if (curR < rows - 1) {
                    int neR = curR + 1;
                    int neC = curC;
                    if (grid[neR] != null
                        && grid[neR].length > neC
                        && grid[neR][neC] == '@'
                        && !visited[neR][neC]) {
                        visited[neR][neC] = true;
                        stack.push(new int[]{neR, neC});
                    }
                }
                // Left
                if (curC > 0) {
                    int neR = curR;
                    int neC = curC - 1;
                    if (grid[neR] != null
                        && grid[neR].length > neC
                        && grid[neR][neC] == '@'
                        && !visited[neR][neC]) {
                        visited[neR][neC] = true;
                        stack.push(new int[]{neR, neC});
                    }
                }
                // Right
                if (curC < grid[curR].length - 1) {
                    int neR = curR;
                    int neC = curC + 1;
                    if (grid[neR] != null
                        && grid[neR].length > neC
                        && grid[neR][neC] == '@'
                        && !visited[neR][neC]) {
                        visited[neR][neC] = true;
                        stack.push(new int[]{neR, neC});
                    }
                }
            }
        }
    }

    return count;
}

