    for (int i = 0; i < rows; i++) {
        if (grid[i] == null) {
            rowLengths[i] = 0;
        } else {
            rowLengths[i] = grid[i].length;
        }
        totalCells += rowLengths[i];
    }
    if (totalCells == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        visited[i] = new boolean[rowLengths[i]];
    }

    int[] stackR = new int[totalCells];
    int[] stackC = new int[totalCells];
    int count = 0;
    // Directions for 8-neighbor connectivity
    int[] dR = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dC = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < rowLengths[r]; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                // Start a new deposit
                int top = 0;
                stackR[top] = r;
                stackC[top] = c;
                top++;
                while (top > 0) {
                    top--;
                    int cr = stackR[top];
                    int cc = stackC[top];
                    if (visited[cr][cc]) {
                        continue;
                    }
                    visited[cr][cc] = true;
                    for (int dir = 0; dir < 8; dir++) {
                        int nr = cr + dR[dir];
                        int nc = cc + dC[dir];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < rowLengths[nr]) {
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                stackR[top] = nr;
                                stackC[top] = nc;
                                top++;
                            }
                        }
                    }
                }
                count++;
            }
        }
    }
    return count;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null) {
        return 0;
    }
    int rows = grid.length;
    if (rows == 0) {
        return 0;
    }
    int cols = grid[0].length;
    if (cols == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            continue;
        }
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                depositCount++;
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.add(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int curR = pos[0];
                    int curC = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = curR + dRow[k];
                        int nc = curC + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && !visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stack.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return depositCount;
}

public static int maxRegions(int N) {
    if (N < 1) {
        throw new IllegalArgumentException("Number of triangles must be at least 1.");
    }
    // Formula derived: maximum regions = 3*N*(N-1) + 2
    return 3 * N * (N - 1) + 2;
}

public static int maxRegions(int N) {
    if (N < 1) {
        // No triangles or invalid input yields no division of the plane
        return 0;
    }
    try {
        long value = 3L * N * N - 3L * N + 2L;
        if (value > Integer.MAX_VALUE) {
            // If result exceeds int range, clamp to Integer.MAX_VALUE
            return Integer.MAX_VALUE;
        }
        return (int) value;
    } catch (ArithmeticException e) {
        // In case of overflow in intermediate multiplication (unlikely with long)
        return Integer.MAX_VALUE;
    }
}

