    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num == 0) {
            if (freq.get(0) > 1) {
                count++;
            }
        } else if (num % 2 == 0) {
            int half = num / 2;
            if (freq.containsKey(half)) {
                count++;
            }
        }
    }
    return count;
}

