public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Basic validation
        if (n <= 0 || start == null || end == null || paths == null
                || start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }
        // We only use the first element as the node id if multiple are provided
        int startNode = start[0];
        int endNode = end[0];

        if (startNode == endNode) {
            return "can be travelled";
        }

        // Build adjacency map
        java.util.Map<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();

        for (int[] edge : paths) {
            if (edge == null || edge.length < 2) {
                continue; // skip invalid edge definitions
            }
            int u = edge[0];
            int v = edge[1];
            adj.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(v);
            adj.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(u);
        }

        // BFS
        java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
        java.util.Set<Integer> visited = new java.util.HashSet<>();

        queue.offer(startNode);
        visited.add(startNode);

        while (!queue.isEmpty()) {
            int node = queue.poll();
            java.util.List<Integer> neighbors = adj.getOrDefault(node, java.util.Collections.emptyList());
            for (int nb : neighbors) {
                if (nb == endNode) {
                    return "can be travelled";
                }
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // In case of any unexpected runtime exception
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Validate basic parameters
        if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
            return "cannot be travelled";
        }

        // Edge case: start equals end
        if (start[0] == end[0] && start[1] == end[1]) {
            return "can be travelled";
        }

        // Build a set of valid path coordinates
        java.util.Set<Long> pathSet = new java.util.HashSet<>();
        if (paths != null) {
            for (int[] coord : paths) {
                if (coord != null && coord.length == 2) {
                    int r = coord[0];
                    int c = coord[1];
                    if (r < 0 || r >= n || c < 0 || c >= n) {
                        continue; // ignore out-of-bounds coordinates
                    }
                    long key = ((long) r) * n + c;
                    pathSet.add(key);
                }
            }
        }

        long startKey = ((long) start[0]) * n + start[1];
        long endKey = ((long) end[0]) * n + end[1];

        // Ensure both start and end are within the set of valid paths
        if (!pathSet.contains(startKey) || !pathSet.contains(endKey)) {
            return "cannot be travelled";
        }

        // BFS to find connectivity
        java.util.Deque<long[]> queue = new java.util.ArrayDeque<>();
        java.util.Set<Long> visited = new java.util.HashSet<>();

        queue.add(new long[] { start[0], start[1] });
        visited.add(startKey);

        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };

        while (!queue.isEmpty()) {
            long[] cur = queue.poll();
            int r = (int) cur[0];
            int c = (int) cur[1];
            long curKey = ((long) r) * n + c;
            if (curKey == endKey) {
                return "can be travelled";
            }

            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) {
                    continue;
                }
                long nextKey = ((long) nr) * n + nc;
                if (!pathSet.contains(nextKey) || visited.contains(nextKey)) {
                    continue;
                }
                visited.add(nextKey);
                queue.add(new long[] { nr, nc });
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // In the event of any unexpected runtime issues, consider travel impossible
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue; // ignore invalid path endpoints
            }
            String a = x1 + "," + y1;
            String b = x2 + "," + y2;
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
    }

    String startKey = sx + "," + sy;
    String endKey = ex + "," + ey;

    // If start equals end
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (visited.contains(nb)) continue;
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(nb);
            queue.add(nb);
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0) {
            return "cannot be travelled";
        }
        if (start == null || end == null || start.length != n || end.length != n) {
            return "cannot be travelled";
        }
        // Edge case: start equals end
        boolean same = true;
        for (int i = 0; i < n; i++) {
            if (start[i] != end[i]) {
                same = false;
                break;
            }
        }
        if (same) {
            return "can be travelled";
        }

        // Build graph representation
        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
        java.util.function.Function<int[], String> coordKey = coord -> java.util.Arrays.toString(coord);

        String startKey = coordKey.apply(start);
        String endKey = coordKey.apply(end);
        graph.computeIfAbsent(startKey, k -> new java.util.ArrayList<>());
        graph.computeIfAbsent(endKey, k -> new java.util.ArrayList<>());

        if (paths != null) {
            for (int[] path : paths) {
                if (path == null || path.length != 2 * n) {
                    continue; // ignore malformed paths
                }
                int[] a = java.util.Arrays.copyOfRange(path, 0, n);
                int[] b = java.util.Arrays.copyOfRange(path, n, 2 * n);
                String keyA = coordKey.apply(a);
                String keyB = coordKey.apply(b);
                graph.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
                graph.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
            }
        }

        // BFS to find if end is reachable
        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String current = queue.poll();
            java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
            for (String neighbor : neighbors) {
                if (!visited.contains(neighbor)) {
                    if (neighbor.equals(endKey)) {
                        return "can be travelled";
                    }
                    visited.add(neighbor);
                    queue.add(neighbor);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // In case of any unexpected errors, assume travel is not possible
        return "cannot be travelled";
    }
}

