public static String appx(String word1, String word2) {
    if (word1 == null) word1 = "";
    if (word2 == null) word2 = "";
    int[] freq1 = new int[256];
    int[] freq2 = new int[256];
    for (char c : word1.toCharArray()) freq1[c]++;
    for (char c : word2.toCharArray()) freq2[c]++;
    long numerator = 0;
    for (int i = 0; i < 256; i++) {
        if (freq1[i] > 0 && freq2[i] > 0) {
            numerator += freq1[i] + freq2[i];
        }
    }
    long denominator = (long) word1.length() + (long) word2.length();
    if (denominator == 0 || numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    long gcd = java.math.BigInteger.valueOf(numerator).gcd(java.math.BigInteger.valueOf(denominator)).longValue();
    numerator /= gcd;
    denominator /= gcd;
    if (numerator == denominator) {
        return "appx(" + word1 + ", " + word2 + ") = 1";
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

public static String appx(String word1, String word2) {
    if (word1 == null) word1 = "";
    if (word2 == null) word2 = "";
    String w1 = word1.toUpperCase();
    String w2 = word2.toUpperCase();
    java.util.Set<Character> set = new java.util.HashSet<>();
    for (char c : w1.toCharArray()) set.add(c);
    int commonCount = 0;
    java.util.Set<Character> commonSet = new java.util.HashSet<>();
    for (char c : w2.toCharArray()) {
        if (set.contains(c)) commonSet.add(c);
    }
    commonCount = commonSet.size();
    if (w1.length() > 1 && w2.length() > 1 && w1.charAt(w1.length() - 1) == w2.charAt(w2.length() - 1)) {
        if (commonSet.contains(w1.charAt(w1.length() - 1))) {
            commonCount--; // exclude last common letter if both end with same letter
        }
    }
    int numerator = 2 * commonCount;
    int denominator = w1.length() + w2.length();
    StringBuilder sb = new StringBuilder();
    sb.append("appx(").append(word1).append(", ").append(word2).append(") = ");
    if (numerator == 0) {
        sb.append("0");
    } else if (numerator == denominator) {
        sb.append("1");
    } else {
        int g = java.lang.Math.abs(gcd(numerator, denominator));
        numerator /= g;
        denominator /= g;
        if (denominator == 1) {
            sb.append(numerator);
        } else {
            sb.append(numerator).append('/').append(denominator);
        }
    }
    return sb.toString();
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int tmp = a % b;
        a = b;
        b = tmp;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid date";
    }
    int monthInt, dayInt, yearInt;
    try {
        monthInt = Integer.parseInt(parts[0]);
        dayInt = Integer.parseInt(parts[1]);
        yearInt = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        return "Invalid date";
    }
    // Basic range checks
    if (monthInt < 1 || monthInt > 12) {
        return "Invalid date";
    }
    if (dayInt < 1 || dayInt > 31) {
        return "Invalid date";
    }
    try {
        java.time.LocalDate localDate = java.time.LocalDate.of(yearInt, monthInt, dayInt);
        String[] monthNames = {"January","February","March","April","May","June","July","August","September","October","November","December"};
        String monthName = monthNames[monthInt - 1];
        java.time.DayOfWeek dow = localDate.getDayOfWeek();
        String[] weekdayNames = {"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};
        String weekdayName = weekdayNames[dow.getValue() - 1];
        return monthName + " " + dayInt + ", " + yearInt + " is a " + weekdayName;
    } catch (java.time.DateTimeException e) {
        return "Invalid date";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date";
    }
    try {
        java.time.format.DateTimeFormatter parser = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, parser);

        java.time.format.DateTimeFormatter monthFormatter = java.time.format.DateTimeFormatter.ofPattern("MMMM");
        java.time.format.DateTimeFormatter weekdayFormatter = java.time.format.DateTimeFormatter.ofPattern("EEEE");

        String month = localDate.format(monthFormatter);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.format(weekdayFormatter);

        return month + " " + day + ", " + year + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        return "Invalid date";
    } catch (Exception e) {
        return "Invalid date";
    }
}

