        java.time.format.DateTimeFormatter inputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, inputFormatter);

        String month = localDate.getMonth()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();

        String weekday = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return month + " " + day + ", " + year + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format. Expected format: MM dd yyyy");
    }
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Invalid date format");
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.Month monthEnum = java.time.Month.of(month);
        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        String monthName = monthEnum.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();
        String dayName = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return String.format("%s %d, %d is a %s", monthName, day, year, dayName);
    } catch (Exception e) {
        return "Invalid date input";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        return null;
    }
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return null;
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        // Month names (1-indexed)
        String[] monthNames = {
            "", "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        // Validate month
        if (month < 1 || month > 12) {
            return null;
        }
        String monthName = monthNames[month];

        // Use Calendar to get the day of week
        java.util.Calendar cal = java.util.Calendar.getInstance();
        cal.clear();
        cal.set(year, month - 1, day); // month is zero-based in Calendar

        int weekdayIndex = cal.get(java.util.Calendar.DAY_OF_WEEK);
        // Weekday names (Calendar: Sunday=1, Monday=2, ..., Saturday=7)
        String[] weekdayNames = {
            "", "Sunday", "Monday", "Tuesday", "Wednesday",
            "Thursday", "Friday", "Saturday"
        };
        String weekdayName = weekdayNames[weekdayIndex];

        // Return formatted string
        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (NumberFormatException | ArrayIndexOutOfBoundsException e) {
        return null;
    } catch (Exception e) {
        // Catch any unexpected exception
        return null;
    }
}

