public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trim = n / 20; // floor of 5% of n
    if (trim * 2 >= n) {
        // Not enough elements to trim; return mean of whatever remains
        long sumAll = 0L;
        for (int v : arr) {
            sumAll += v;
        }
        return (double) sumAll / n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0L;
    for (int i = trim; i < n - trim; i++) {
        sum += sorted[i];
    }
    return (double) sum / (n - 2 * trim);
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }
    int n = arr.length;
    int k = (int) Math.floor(n * 0.05);
    if (k < 0) k = 0;
    if (n - 2 * k <= 0) {
        throw new IllegalArgumentException("Not enough elements after trimming.");
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0L;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (double) (n - 2 * k);
}

public double trimMean(int[] arr) {
