    long sum = 0L;
    int start = remove;
    int end = n - remove; // exclusive upper bound
    if (start >= end) {
        return 0.0;
    }
    for (int i = start; i < end; i++) {
        sum += sorted[i];
    }
    int count = end - start;
    return sum / (double) count;
