public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    if (arr.length % 2 != 0) {
        return false;
    }
    int n = arr.length;
    int[] freq = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k; // ensure non‑negative
        freq[r]++;
    }
    // remainder 0 must be even
    if (freq[0] % 2 != 0) {
        return false;
    }
    // if k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        int half = k / 2;
        if (freq[half] % 2 != 0) {
            return false;
        }
    }
    // check other remainders
    for (int r = 1; r < k / 2 + 1; r++) {
        int complement = (k - r) % k;
        if (r == complement) { // already handled when k is even
            continue;
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false; // invalid input
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair odd number of elements
    }
    if (n == 0) {
        return true; // empty array can be considered trivially paired
    }

    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // normalize to non-negative remainder
        count[rem]++;
    }

    // remainder 0 must have an even count
    if (count[0] % 2 != 0) {
        return false;
    }

    // For each remainder r, its complement must have the same count
    // Special case when r == complement (i.e., 2*r % k == 0), requires even count
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        int complement = k - r;
        if (r == complement) {
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[complement]) {
                return false;
            }
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    if (n == 0) {
        return true;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq.merge(rem, 1, Integer::sum);
    }
    java.util.HashSet<Integer> processed = new java.util.HashSet<>();
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int r = entry.getKey();
        if (processed.contains(r)) {
            continue;
        }
        int count = entry.getValue();
        if (r == 0) {
            if (count % 2 != 0) {
                return false;
            }
        } else if (k % 2 == 0 && r == k / 2) {
            if (count % 2 != 0) {
                return false;
            }
        } else {
            int comp = (k - r) % k;
            int compCount = freq.getOrDefault(comp, 0);
            if (count != compCount) {
                return false;
            }
            processed.add(comp);
        }
        processed.add(r);
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int val : arr) {
        int r = val % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, middle remainder k/2 must also have even count
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    // Other remainders must pair up
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // middle remainder for even k handled above
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Handle null or empty array
    if (arr == null || arr.length == 0) {
        return true; // empty array can be considered trivially pairable
    }

    int n = arr.length;
    // Must be even number of elements to form pairs
    if (n % 2 != 0) {
        return false;
    }

    // Divisor must be positive to avoid undefined modulo
    if (k <= 0) {
        return false;
    }

    int[] freq = new int[k];
    // Count frequency of each remainder
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // normalize negative numbers
        freq[rem]++;
    }

    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, the remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // For all other remainders, freq[r] must equal freq[k-r]
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // This case is handled above for even k
            continue;
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    try {
        if (n <= 0 || edges == null || hasApple == null || edges.length != n - 1 || hasApple.length != n) {
            throw new IllegalArgumentException("Invalid input");
        }
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            if (edge == null || edge.length != 2) {
                throw new IllegalArgumentException("Invalid edge format");
            }
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                throw new IllegalArgumentException("Edge contains out-of-range node");
            }
            graph[u].add(v);
            graph[v].add(u);
        }
        final int[] totalTime = {0};

        java.util.function.BiFunction<Integer, Integer, Boolean> dfs = new java.util.function.BiFunction<Integer, Integer, Boolean>() {
            @Override
            public Boolean apply(Integer node, Integer parent) {
                boolean subtreeHasApple = hasApple[node];
                for (int neighbor : graph[node]) {
                    if (!neighbor.equals(parent)) {
                        boolean childHasApple = this.apply(neighbor, node);
                        if (childHasApple) {
                            totalTime[0] += 2;
                            subtreeHasApple = true;
                        }
                    }
                }
                return subtreeHasApple;
            }
        };

        dfs.apply(0, -1);
        return totalTime[0];
    } catch (Exception e) {
        return 0;
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n) {
