    if (edges == null || edges.length == 0) {
        // No edges; only node 0 exists. If it has an apple, no traversal needed.
        return 0;
    }
    // Build adjacency list
    List<int[]> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new int[0]); // placeholder, will convert to proper list later
    }
