        if (e == null || e.length < 2) continue; // skip invalid edge
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue; // skip out-of-bounds
        graph[u].add(v);
        graph[v].add(u);
    }
    boolean[] visited = new boolean[n];
