private boolean dfs(int node, boolean[] visited, ArrayList<Integer>[] graph, boolean[] hasApple, int[] time) {
    visited[node] = true;
    boolean hasAppleSubtree = hasApple[node];
    for (int nei : graph[node]) {
        if (!visited[nei]) {
            boolean childHasApple = dfs(nei, visited, graph, hasApple, time);
            if (childHasApple) {
                time[0] += 2; // traverse this edge twice
                hasAppleSubtree = true;
            }
        }
    }
    return hasAppleSubtree;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Validate inputs
    if (n <= 0) {
        return 0;
    }
    if (edges == null || edges.length < n - 1) {
        throw new IllegalArgumentException("Invalid edges for a tree of size " + n);
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple array length must match n");
    }

    // Build adjacency list
    ArrayList<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) {
            throw new IllegalArgumentException("Invalid edge format");
        }
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge vertices out of bounds");
        }
        graph[u].add(v);
        graph[v].add(u);
    }

    int[] time = new int[]{0};

    // DFS helper to determine whether a subtree has any apple
    java.util.function.BiFunction<Integer, Integer, Boolean> dfs = new java.util.function.BiFunction<Integer, Integer, Boolean>() {
        @Override
        public Boolean apply(Integer node, Integer parent) {
            boolean hasInSubtree = hasApple[node];
            for (Integer neighbor : graph[node]) {
                if (neighbor == parent) {
                    continue;
                }
                boolean childHas = apply(neighbor, node);
                if (childHas) {
                    time[0] += 2; // traverse to child and back
                    hasInSubtree = true;
                }
            }
            return hasInSubtree;
        }
    };

    dfs.apply(0, -1);
    return time[0];
}

