    }
    int[] idx = new int[n];
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        adj[u][idx[u]++] = v;
        adj[v][idx[v]++] = u;
    }

    // Iterative post‑order DFS to compute necessary edges
    int[] nodeStack = new int[n];
    int[] parentStack = new int[n];
    boolean[] visitedStack = new boolean[n];
    int top = 0;
    nodeStack[0] = 0;
    parentStack[0] = -1;
    visitedStack[0] = false;

    int total = 0;
    boolean[] hasSub = new boolean[n];

    while (top >= 0) {
        int node = nodeStack[top];
        int parent = parentStack[top];
        if (!visitedStack[top]) {
            visitedStack[top] = true;
            for (int child : adj[node]) {
                if (child == parent) continue;
                top++;
                nodeStack[top] = child;
                parentStack[top] = node;
                visitedStack[top] = false;
            }
        } else {
            boolean has = hasApple[node];
            for (int child : adj[node]) {
                if (child == parent) continue;
                if (hasSub[child]) {
                    total += 2;
                    has = true;
                }
            }
            hasSub[node] = has;
            top--;
        }
    }

    return total;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        return 0;
    }

    // Build adjacency list
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length < 2) continue;
            int u = e[0], v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            graph[u].add(v);
            graph[v].add(u);
        }
    }

    // Prepare for iterative post-order traversal
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    java.util.List<Integer> order = new java.util.ArrayList<>();

    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            parent[nei] = node;
            stack.push(nei);
        }
    }

    int[] time = new int[n];
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        int subTime = 0;
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            subTime += time[nei];
        }

        if (node == 0) {
            time[node] = subTime;
        } else if (subTime > 0 || hasApple[node]) {
            time[node] = subTime + 2;
        } else {
            time[node] = subTime;
        }
    }

    return time[0];
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c >= 'a' && c <= 'z') {
            freq[c - 'a']++;
        } else {
            // If the string may contain other characters, we ignore them
            // as the problem description implies only lowercase letters.
        }
    }
    StringBuilder sb = new StringBuilder(s.length());
    int total = s.length();

    while (total > 0) {
        // Forward pass: smallest to largest
        for (int i = 0; i < 26 && total > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                total--;
            }
        }
        // Backward pass: largest to smallest
        for (int i = 25; i >= 0 && total > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                total--;
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s != null ? "" : null;
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.merge(ch, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest to largest
        for (java.util.Map.Entry<Character, Integer> entry : freq.entrySet()) {
            if (entry.getValue() > 0) {
                sb.append(entry.getKey());
                entry.setValue(entry.getValue() - 1);
                remaining--;
            }
        }
        // Descending pass: pick largest to smallest
        for (Character key : ((java.util.NavigableMap<Character, Integer>) freq).descendingKeySet()) {
            int cnt = freq.get(key);
            if (cnt > 0) {
                sb.append(key);
                freq.put(key, cnt - 1);
                remaining--;
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    final int MAX_CHAR = 65535; // maximum value for a Java char
    int[] freq = new int[MAX_CHAR + 1];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }

    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();

    while (remaining > 0) {
        // Step 1: pick the smallest character
        int ch = -1;
        for (int i = 0; i <= MAX_CHAR; i++) {
            if (freq[i] > 0) {
                ch = i;
                break;
            }
        }
        if (ch == -1) break; // no characters left (shouldn't happen)
        result.append((char) ch);
        freq[ch]--;
        remaining--;
        int last = ch;

        // Step 2: pick smallest characters greater than the last appended
        while (true) {
            int next = -1;
            for (int i = last + 1; i <= MAX_CHAR; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) next);
            freq[next]--;
            remaining--;
            last = next;
        }

        if (remaining == 0) break;

        // Step 4: pick the largest character
        int chMax = -1;
        for (int i = MAX_CHAR; i >= 0; i--) {
            if (freq[i] > 0) {
                chMax = i;
                break;
            }
        }
        if (chMax == -1) break;
        result.append((char) chMax);
        freq[chMax]--;
        remaining--;
        int lastMax = chMax;

        // Step 5: pick largest characters smaller than the last appended
        while (true) {
            int next = -1;
            for (int i = lastMax - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) next);
            freq[next]--;
            remaining--;
            lastMax = next;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    try {
        TreeMap<Character, Integer> freq = new TreeMap<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            freq.put(ch, freq.getOrDefault(ch, 0) + 1);
        }
        StringBuilder result = new StringBuilder();
        while (!freq.isEmpty()) {
            // Ascending part
            Character ascKey = freq.firstKey();
            result.append(ascKey);
            decrement(freq, ascKey);
            char last = ascKey;
            while (true) {
                Character nextAsc = freq.higherKey(last);
                if (nextAsc == null) break;
                result.append(nextAsc);
                decrement(freq, nextAsc);
                last = nextAsc;
            }
            if (freq.isEmpty()) break;
            // Descending part
            Character descKey = freq.lastKey();
            result.append(descKey);
            decrement(freq, descKey);
            last = descKey;
            while (true) {
                Character nextDesc = freq.lowerKey(last);
                if (nextDesc == null) break;
                result.append(nextDesc);
                decrement(freq, nextDesc);
                last = nextDesc;
            }
        }
        return result.toString();
    } catch (Exception e) {
        return null;
    }
}

private void decrement(TreeMap<Character, Integer> freq, Character key) {
    Integer count = freq.get(key);
    if (count == null) return;
    if (count <= 1) {
        freq.remove(key);
    } else {
        freq.put(key, count - 1);
    }
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char ch : s.toCharArray()) {
        freq.merge(ch, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending pass
        java.util.Map.Entry<Character, Integer> firstEntry = freq.firstEntry();
        if (firstEntry == null) break;
        char last = firstEntry.getKey();
        result.append(last);
        int cnt = freq.get(last);
        if (cnt == 1) {
            freq.remove(last);
        } else {
            freq.put(last, cnt - 1);
        }

        while (true) {
            java.util.Map.Entry<Character, Integer> higher = freq.higherEntry(last);
            if (higher == null) break;
            last = higher.getKey();
            result.append(last);
            cnt = freq.get(last);
            if (cnt == 1) {
                freq.remove(last);
            } else {
                freq.put(last, cnt - 1);
            }
        }

        if (freq.isEmpty()) break;

        // Descending pass
        last = freq.lastKey();
        result.append(last);
        cnt = freq.get(last);
        if (cnt == 1) {
            freq.remove(last);
        } else {
            freq.put(last, cnt - 1);
        }

        while (true) {
            java.util.Map.Entry<Character, Integer> lower = freq.lowerEntry(last);
            if (lower == null) break;
            last = lower.getKey();
            result.append(last);
            cnt = freq.get(last);
            if (cnt == 1) {
                freq.remove(last);
            } else {
                freq.put(last, cnt - 1);
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) totalSum += num;
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        long target = totalSum * k / n;
        @SuppressWarnings("unchecked")
        java.util.Set<Long>[] subsets = new java.util.HashSet[k + 1];
        for (int i = 0; i <= k; i++) subsets[i] = new java.util.HashSet<>();
        subsets[0].add(0L);
        for (int num : nums) {
            long val = num;
            for (int j = Math.min(k - 1, n - 1); j >= 0; j--) {
                for (long s : subsets[j]) {
                    subsets[j + 1].add(s + val);
                }
            }
            if (subsets[k].contains(target)) return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long sum = 0L;
    for (int v : nums) {
        sum += v;
    }
    int maxK = n / 2;
    // dp[k] stores all possible sums for subsets of size k
    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] dp = new java.util.HashSet[maxK + 1];
    for (int k = 0; k <= maxK; k++) {
        dp[k] = new java.util.HashSet<>();
    }
    dp[0].add(0L);
    for (int num : nums) {
        // iterate k in reverse to avoid using the same number twice
        for (int k = Math.min(maxK, n); k >= 1; k--) {
            for (Long prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((sum * k) % n != 0) {
            continue;
        }
        long target = (sum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[i][s] true if a subset of size i sums to s
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate backwards to avoid reuse
        for (int i = n - 1; i >= 0; i--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[i][s]) {
                    dp[i + 1][s + num] = true;
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int total = 0;
    for (int v : nums) {
        total += v;
    }

    // sums[k] will contain all possible sums of subsets of size k
    List<Set<Integer>> sums = new ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        sums.add(new HashSet<>());
    }
    sums.get(0).add(0);

    for (int num : nums) {
        // update from large k to small to avoid reusing the same element in the same iteration
        for (int k = n; k >= 1; k--) {
            if (!sums.get(k - 1).isEmpty()) {
                for (int prevSum : sums.get(k - 1)) {
                    sums.get(k).add(prevSum + num);
                }
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        if (sums.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int fromPrev = dp[i - 1] + cost[i - 1];
        int fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 0;
    }
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int fromOne = prev1 + cost[i - 1];
        int fromTwo = prev2 + cost[i - 2];
        int curr = Math.min(fromOne, fromTwo);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 0 or 1; reaching the top is stepping over step 0, cost 0
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int payOneStep = dp[i - 1] + cost[i - 1];
        int payTwoSteps = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(payOneStep, payTwoSteps);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

