    if (k > 20) { // 2^k would be too large to store in a boolean array for typical constraints
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    if (total > n - k + 1) { // not enough substrings to cover all possibilities
        return false;
    }

    boolean[] seen = new boolean[total];
    int seenCount = 0;
    int code = 0;

    // Build the initial window
    for (int i = 0; i < k; i++) {
