        seenCount++;
    }
    if (seenCount == total) {
        return true;
    }

    int mask = total - 1; // keep only k bits
    for (int i = k; i < n; i++) {
        // Slide the window: remove leftmost bit and add new rightmost bit
        code = ((code << 1) + (s.charAt(i) - '0')) & mask;
        if (!seen[code]) {
