public boolean hasAllCodes(String s, int k) {
    if (k <= 0) {
        // By convention, the empty string is considered a substring of any string.
        return true;
    }
    int n = s.length();
    if (k > n) {
        return false; // cannot contain any substring of length k
    }
    // If k is too large to handle with an integer array comfortably,
    // the number of possible codes will exceed the number of substrings.
    if (k > 20) {
        long totalNeeded = 1L << k; // may overflow for large k, but k>20 ensures it's huge
        if (totalNeeded > (long)(n - k + 1)) {
            return false;
        }
        return false; // cannot store all codes in memory
    }

    int totalCodes = 1 << k;
    if (n - k + 1 < totalCodes) {
        return false; // Not enough substrings
    }

    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;

    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    if (!seen[mask]) {
        seen[mask] = true;
        seenCount++;
    }

    int maskBits = totalCodes - 1;
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskBits) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            seenCount++;
            if (seenCount == totalCodes) {
                return true;
            }
        }
    }
    return seenCount == totalCodes;
}

