public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int i0 = n / 2 + n % 2; // first index with arr[i] > n
    int m = n - i0; // number of surplus elements
    if (m <= 0) {
        return 0;
    }
    long sumI = ((long) i0 + (n - 1)) * m / 2; // sum of indices from i0 to n-1
    long surplus = 2L * sumI - (long) (n - 1) * m;
    return (int) surplus;
}

