    if (n < 1) {
        throw new IllegalArgumentException("n must be at least 1");
    }
    long result;
    if ((n & 1) == 0) { // even n
        long k = n / 2L;
        result = k * k;
    } else { // odd n
        long k = (n - 1L) / 2L;
        result = k * (k + 1L);
    }
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("result exceeds integer range");
    }
    return (int) result;
}

