    // If n is non-positive, no operations are needed (invalid but handled gracefully).
    if (n <= 0) {
        return 0;
    }
    // The target value for each element after equalization is n (sum of first n odd numbers is n^2).
    // The minimal number of unit moves equals the sum of positive differences from the target.
    // This simplifies to k * (n - k), where k = ceil(n/2).
    long k = (long) (n + 1) / 2;          // ceil(n/2)
    long operations = k * (n - k);        // product fits in long
    // Since the signature expects an int, cast carefully.
    if (operations > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE; // or throw an exception if overflow should not be allowed
    }
    return (int) operations;
}

