        }
    }
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int m = k - small.size();
        return large.get(large.size() - m);
    }
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    try {
        int limit = (int) Math.sqrt(n);
        int[] small = new int[limit + 1];
        int[] big = new int[limit + 1];
        int smallCount = 0;
        int bigCount = 0;

        for (int i = 1; i <= limit; i++) {
            if (n % i == 0) {
                small[smallCount++] = i;
                int other = n / i;
                if (other != i) {
                    big[bigCount++] = other;
                }
            }
        }

        int total = smallCount + bigCount;
        if (k > total) {
            return -1;
        }
        if (k <= smallCount) {
            return small[k - 1];
        } else {
            // Determine position in big factors (descending order)
            int bigIndexFromEnd = bigCount - (k - smallCount);
            if (bigIndexFromEnd < 0 || bigIndexFromEnd >= bigCount) {
                return -1;
            }
            return big[bigIndexFromEnd];
        }
    } catch (Exception e) {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    // Validate input
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int sqrt = (int) Math.sqrt(n);
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();

    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int paired = n / i;
            if (i != paired) {
                large.add(paired);
            }
        }
    }

    int totalCount = small.size() + large.size();
    if (k > totalCount) {
        return -1;
    }

    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int indexInLarge = k - small.size() - 1; // position when reversed
        int reversedIndex = large.size() - 1 - indexInLarge;
        return large.get(reversedIndex);
    }
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (i != other) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (Math.abs(last - c) == 32) { // opposite case letters
                sb.setLength(len - 1); // remove the pair
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

