public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int maxCount = 0;
    // There are n-1 possible split positions
    int limit = 1 << (n - 1);
    for (int mask = 0; mask < limit; mask++) {
        HashSet<String> seen = new HashSet<>();
        int start = 0;
        boolean valid = true;
        int count = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // split after position i
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                start = i + 1;
                count++;
            }
        }
        if (!valid) {
            continue;
        }
        // add the last substring
        String last = s.substring(start, n);
        if (!seen.add(last)) {
            continue;
        }
        count++;
        if (count > maxCount) {
            maxCount = count;
        }
    }
    return maxCount;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    final int[] best = new int[1];
    java.util.HashSet<String> used = new java.util.HashSet<>();
    dfs(0, used, 0, s, best);
    return best[0];
}

private void dfs(int pos, java.util.Set<String> used, int count, String s, int[] best) {
    if (pos == s.length()) {
        if (count > best[0]) {
            best[0] = count;
        }
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, count + 1, s, best);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    return helper(0, s, new HashSet<>());
}

private int helper(int idx, String s, Set<String> used) {
    int n = s.length();
    if (idx == n) {
        return 0; // no more characters to split
    }
    int maxParts = 0;
    for (int end = idx + 1; end <= n; end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int parts = 1 + helper(end, s, used);
            if (parts > maxParts) {
                maxParts = parts;
            }
            used.remove(sub);
        }
    }
    return maxParts;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int[] max = {0};
    backtrack(s, 0, new HashSet<>(), 0, max);
    return max[0];
}

private void backtrack(String s, int index, Set<String> used, int count, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int i = index + 1; i <= s.length(); i++) {
        String part = s.substring(index, i);
        if (!used.contains(part)) {
            used.add(part);
            backtrack(s, i, used, count + 1, max);
            used.remove(part);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    return dfs(s, 0, new java.util.HashSet<String>());
}

private int dfs(String s, int pos, java.util.Set<String> used) {
    if (pos == s.length()) {
        return used.size();
    }
    int best = 0;
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int current = dfs(s, end, used);
            if (current > best) {
                best = current;
            }
            used.remove(sub);
        }
    }
    return best;
}

