    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k is out of valid range");
    }

    int remaining = k - minSum;      // how much we need to add to the base string of 'a's
    char[] result = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // increase characters from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can at most go from 'a' to 'z'
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

