public static int singleNumber(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (nums.length == 0) {
        return 0; // or throw new IllegalArgumentException("Input array cannot be empty");
    }

    int ones = 0;   // bits that appeared once so far
    int twos = 0;   // bits that appeared twice so far

    for (int num : nums) {
        // Update bits that appeared twice
        twos |= ones & num;
        // Update bits that appeared once
        ones ^= num;
        // Bits that appeared three times are removed from both ones and twos
        int mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

