public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (high < 0 || low > high) {
        return result;
    }
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long child = num * 10 + (lastDigit - 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
        if (lastDigit < 9) {
            long child = num * 10 + (lastDigit + 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    // Handle negative bounds: stepping numbers are non‑negative
    if (high < 0) {
        return result;
    }
    if (low < 0) {
        low = 0;
    }
    if (low > high) {
        return result;
    }

    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    // Initialise the queue with single digit numbers
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) {
            continue;
        }
        if (cur >= low) {
            result.add((int) cur);
        }
        // Do not expand 0 to avoid leading zero numbers
        if (cur == 0) {
            continue;
        }
        int lastDigit = (int) (cur % 10);

        if (lastDigit > 0) {
            long next = cur * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = cur * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    java.util.Collections.sort(result);
    return result;
}

