    }
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.add((long) i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        long nextDigit1 = lastDigit + 1;
        long nextDigit2 = lastDigit - 1;
        if (nextDigit1 <= 9) {
            long nextNum = num * 10 + nextDigit1;
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
        if (nextDigit2 >= 0) {
            long nextNum = num * 10 + nextDigit2;
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
    }
    java.util.Collections.sort(result);
