        int next2 = lastDigit + 1;
        if (next1 >= 0) {
            long nextNum = curr * 10 + next1;
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (next2 <= 9) {
            long nextNum = curr * 10 + next2;
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    result.sort(null);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    // Handle invalid range
    if (low > high) {
        return result;
    }
    // Include 0 if within range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    // Start BFS with single digits 1-9
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer((long) i);
        }
    }
    while (!queue.isEmpty()) {
        long curr = queue.poll();
        if (curr >= low && curr <= high) {
            result.add((int) curr);
        }
        // If curr is already > high, further extensions are unnecessary
        if (curr > high) {
            continue;
        }
        int lastDigit = (int) (curr % 10);
        // Generate next possible digits
        if (lastDigit > 0) {
            long next = curr * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = curr * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long pos = 1;
    while (pos <= n) {
        long high = n / (pos * 10);
        long cur = (n / pos) % 10;
        long low = n % pos;
        if (cur == 0) {
            count += high * pos;
        } else if (cur == 1) {
            count += high * pos + low + 1;
        } else {
            count += (high + 1) * pos;
        }
        if (pos > Long.MAX_VALUE / 10) {
            break; // prevent overflow on next multiplication
        }
        pos *= 10;
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    long result = 0;
    long factor = 1;
    long num = n;
    while (factor <= num) {
        long lower = num % factor;
        long cur = (num / factor) % 10;
        long higher = num / (factor * 10);

        if (cur == 0) {
            result += higher * factor;
        } else if (cur == 1) {
            result += higher * factor + lower + 1;
        } else {
            result += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower = n - (n / factor) * factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long pos = 1;
    long count = 0;
    while (n / pos > 0) {
        long fullCycles = n / (pos * 10);
        count += fullCycles * pos;
        long remainder = n % (pos * 10);
        long add = Math.max(0, remainder - pos + 1);
        count += add;
        pos *= 10;
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (n / factor != 0) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // Power of two is only defined for positive integers.
    if (n <= 0) {
        return false;
    }
    // A number that is a power of two has exactly one bit set.
    // Thus n & (n - 1) should be zero.
    return (n & (n - 1)) == 0;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
