    }
    // A number is a power of two if it has exactly one bit set.
    // In binary, numbers of the form 2^x have only one 1 bit and all others 0.
    // The expression (n & (n - 1)) clears the lowest set bit; if the result is 0,
    // then n had only one set bit.
    return (n & (n - 1)) == 0;
}

