    // The expression (n & (n - 1)) clears the lowest set bit. If the result is 0, n had only one set bit.
    // Zero and negative numbers are not considered powers of two.
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

