public static int longestLine(int[][] mat) {
    // Validate input
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;

    // Previous row direction arrays
    int[] prevV = new int[n];
    int[] prevDiag = new int[n];
    int[] prevAnti = new int[n];

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        int[] curV = new int[n];
        int[] curDiag = new int[n];
        int[] curAnti = new int[n];

        int horiz = 0;

        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                horiz = horiz + 1;

                // Vertical
                int vert = prevV[j] + 1;

                // Diagonal
                int diag = (j > 0 ? prevDiag[j - 1] : 0) + 1;

                // Anti-diagonal
                int anti = (j < n - 1 ? prevAnti[j + 1] : 0) + 1;

                // Update current arrays
                curV[j] = vert;
                curDiag[j] = diag;
                curAnti[j] = anti;

                // Update maximum length
                int localMax = Math.max(Math.max(horiz, vert), Math.max(diag, anti));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                // If the cell is 0, all directions reset to 0
                horiz = 0;
                curV[j] = 0;
                curDiag[j] = 0;
                curAnti[j] = 0;
            }
        }

        // Prepare for next row
        prevV = curV;
        prevDiag = curDiag;
        prevAnti = curAnti;
    }

    return maxLen;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
