    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            continue;
        }
        for (int j = 0; j < n; j++) {
            try {
                if (mat[i][j] == 1) {
                    horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                    vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                    diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                    anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                    int cellMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                           Math.max(diag[i][j], anti[i][j]));
                    if (cellMax > max) {
                        max = cellMax;
                    }
                } else {
                    horiz[i][j] = 0;
                    vert[i][j] = 0;
                    diag[i][j] = 0;
                    anti[i][j] = 0;
                }
            } catch (Exception e) {
                // In case of unexpected runtime issue, treat cell as 0
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return max;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
