    }
    int m = mat.length;
    // DP arrays for each direction
    int[][] H = new int[m][];   // horizontal
    int[][] V = new int[m][];   // vertical
    int[][] D = new int[m][];   // diagonal
    int[][] AD = new int[m][];  // anti-diagonal
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        int[] row = mat[i];
        if (row == null) {
            continue; // treat as all zeros
        }
        int n = row.length;
