                V[i][j] = (i > 0 ? V[i - 1][j] : 0) + 1;
                D[i][j] = (i > 0 && j > 0 ? D[i - 1][j - 1] : 0) + 1;
                AD[i][j] = (i > 0 && j < n - 1 ? AD[i - 1][j + 1] : 0) + 1;
                int currentMax = Math.max(Math.max(H[i][j], V[i][j]),
                                           Math.max(D[i][j], AD[i][j]));
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            }
            // If row[j] != 1, all DP entries remain 0 by default
        }
    }
    return maxLen;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // dp[0] - horizontal, dp[1] - vertical, dp[2] - diagonal, dp[3] - anti-diagonal
    int[][][] dp = new int[4][m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        // skip null rows to be safe
        if (mat[i] == null) continue;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[0][i][j] = 1 + (j > 0 ? dp[0][i][j - 1] : 0);
                dp[1][i][j] = 1 + (i > 0 ? dp[1][i - 1][j] : 0);
                dp[2][i][j] = 1 + (i > 0 && j > 0 ? dp[2][i - 1][j - 1] : 0);
                dp[3][i][j] = 1 + (i > 0 && j < n - 1 ? dp[3][i - 1][j + 1] : 0);
                int curMax = Math.max(Math.max(dp[0][i][j], dp[1][i][j]),
                                      Math.max(dp[2][i][j], dp[3][i][j]));
                if (curMax > max) {
                    max = curMax;
                }
            }
        }
    }
    return max;
}

