public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long value = Math.abs((long) n); // use long to handle Integer.MIN_VALUE
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (value > 0) {
        sb.append(value % 10);
        value /= 10;
        digitCount++;
        if (value > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static String addThousandSeparator(int n) {
