    long value = Math.abs((long) n); // use long to avoid overflow on Integer.MIN_VALUE
    StringBuilder sb = new StringBuilder();

    if (value == 0) {
        sb.append('0');
    } else {
        while (value > 0) {
            long part = value % 1000;
            value /= 1000;
            if (value > 0) {
                sb.append(String.format("%03d", part));
                sb.append('.');
            } else {
                sb.append(Long.toString(part));
            }
        }
    }

    if (negative) {
        sb.append('-');
    }

    return sb.reverse().toString();
}

