public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = arr[i] + arr[j];
                int r = (int) Math.sqrt(sum);
                ok[i][j] = r * r == sum;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue;
                if (!ok[last][nxt]) continue;
                if (nxt > 0 && arr[nxt] == arr[nxt - 1] && ( (mask & (1 << (nxt - 1))) == 0)) continue;
                int newMask = mask | (1 << nxt);
                dp[newMask][nxt] += cur;
            }
        }
    }
    long ans = 0;
    for (int i = 0; i < n; i++) ans += dp[fullMask][i];
    return (int) ans;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    java.util.HashMap<String, Long> memo = new java.util.HashMap<>();

    java.util.function.LongBinaryOperator combine = (Long a, Long b) -> a + b;

    // Helper to check perfect square
    java.util.function.IntPredicate isPerfectSquare = (int sum) -> {
        int root = (int) Math.sqrt(sum);
        return root * root == sum;
    };

    java.util.function.Function<Integer, java.util.function.IntUnaryOperator> dfs = new java.util.function.Function<Integer, java.util.function.IntUnaryOperator>() {
        @Override
        public java.util.function.IntUnaryOperator apply(Integer pos) {
            return (lastIndex) -> {
                if (pos == n) {
                    return 1L;
                }
                String key = pos + "," + lastIndex + "," + java.util.Arrays.toString(used);
                if (memo.containsKey(key)) {
                    return memo.get(key);
                }
                long count = 0;
                for (int i = 0; i < n; i++) {
                    if (used[i]) continue;
                    if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
                    if (lastIndex == -1 || isPerfectSquare.test(A[lastIndex] + A[i])) {
                        used[i] = true;
                        count += dfs.apply(pos + 1).apply(i);
                        used[i] = false;
                    }
                }
                memo.put(key, count);
                return count;
            };
        }
    };

    long result = dfs.apply(0).apply(-1);
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to 2*max(A)
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; ++i) {
        isSquare[i * i] = true;
    }

    // Count frequencies of each value
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
    }

    // Precompute factorials up to n
    long[] fact = new long[n + 1];
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;

    // DP: dp[mask][last] = number of ways for subset mask ending at index last
    int totalMask = 1 << n;
    long[][] dp = new long[totalMask][n];
    for (int i = 0; i < n; ++i) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask < totalMask; ++mask) {
        for (int last = 0; last < n; ++last) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int nxt = 0; nxt < n; ++nxt) {
                if ((mask & (1 << nxt)) == 0) {
                    if (isSquare[A[last] + A[nxt]]) {
                        dp[mask | (1 << nxt)][nxt] += cur;
                    }
                }
            }
        }
    }

    long total = 0;
    int fullMask = totalMask - 1;
    for (int i = 0; i < n; ++i) {
        total += dp[fullMask][i];
    }

    // Divide by factorial of frequency of each duplicate value
    long denom = 1;
    for (int count : freqMap.values()) {
        denom *= fact[count];
    }

    return (int)(total / denom);
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    // Precompute square numbers up to max possible sum
    int maxVal = arr[n - 1];
    int maxSum = maxVal + maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; s * s <= maxSum; s++) {
        isSquare[s * s] = true;
    }
    // adjacency lists
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[arr[i] + arr[j]]) {
                adj[i].add(j);
            }
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] memo = new long[1 << n][n];
