public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    boolean[] visited = new boolean[n];
    final int[] res = {0};

    class Helper {
        void dfs(int level, int prev) {
            if (level == n) {
                res[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
                if (level > 0 && !isPerfectSquare(A[i] + prev)) continue;
                visited[i] = true;
                dfs(level + 1, A[i]);
                visited[i] = false;
            }
        }

        private boolean isPerfectSquare(int sum) {
            int root = (int) Math.sqrt(sum);
            return root * root == sum;
        }
    }

    new Helper().dfs(0, -1);
    return res[0];
}

