public static int[] diagonalOrder(int[][] mat) {
    try {
        if (mat == null || mat.length == 0) {
            return new int[0];
        }
        int m = mat.length;
        int n = mat[0].length;
        if (n == 0) {
            return new int[0];
        }
        // Validate all rows for consistent length
        for (int i = 1; i < m; i++) {
            if (mat[i] == null || mat[i].length != n) {
                return new int[0];
            }
        }
        int total = m * n;
        int[] res = new int[total];
        int idx = 0;
        for (int k = 0; k <= m + n - 2; k++) {
            int startRow = Math.max(0, k - (n - 1));
            int endRow = Math.min(m - 1, k);
            if (k % 2 == 0) {
                for (int row = endRow; row >= startRow; row--) {
                    res[idx++] = mat[row][k - row];
                }
            } else {
                for (int row = startRow; row <= endRow; row++) {
                    res[idx++] = mat[row][k - row];
                }
            }
        }
        return res;
    } catch (Exception e) {
        return new int[0];
    }
}

