public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int count = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char current = s.charAt(i);
        if (current == prev) {
            count++;
        } else {
            if (count > max) {
                max = count;
            }
            count = 1;
            prev = current;
        }
    }
    return Math.max(max, count);
}

