public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    int count = 0;
    while (count < n) {
        result.add(current);
        count++;
        long next = (long) current * 10;
        if (next <= n) {
            current = (int) next;
        } else {
            while ((current % 10 == 9) || (((long) current + 1) > n)) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long current = 1;
    long limit = n;
    for (int i = 0; i < n; i++) {
        result.add((int) current);
        if (current * 10 <= limit) {
            current *= 10;
        } else {
            if (current % 10 != 9 && current + 1 <= limit) {
                current++;
            } else {
                while (current / 10 % 10 == 9) {
                    current /= 10;
                }
                current = current / 10 + 1;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int curr, int n, List<Integer> result) {
    if (curr > n) {
        return;
    }
    result.add(curr);
    for (int d = 0; d <= 9; d++) {
        long nextLong = (long) curr * 10 + d;
        if (nextLong > Integer.MAX_VALUE) {
            // Further numbers will be too large, stop exploring this branch
            break;
        }
        int next = (int) nextLong;
        if (next > n) {
            // Since next increases with d, we can break to avoid unnecessary checks
            break;
        }
        dfs(next, n, result);
    }
}

