            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int sum = 0;
    java.util.HashSet<Integer> seen = new java.util.HashSet<>();
    java.util.HashSet<Integer> duplicates = new java.util.HashSet<>();
    for (int value : nums) {
        if (duplicates.contains(value)) {
            continue; // already counted as duplicate, skip
        }
        if (seen.contains(value)) {
            // second occurrence: remove the previously added value from sum
            sum -= value;
            duplicates.add(value);
        } else {
            seen.add(value);
            sum += value;
        }
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    try {
        java.util.Map<Integer, Integer> counter = new java.util.HashMap<>();
        for (int num : nums) {
            counter.put(num, counter.getOrDefault(num, 0) + 1);
        }
        long sum = 0L;
        for (java.util.Map.Entry<Integer, Integer> entry : counter.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }
        return (int) sum;
    } catch (Exception e) {
        // If any unexpected exception occurs, return 0 as a safe fallback.
        return 0;
    }
}

