public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    // Trim possible leading/trailing spaces but preserve internal word separation
    // We'll split on spaces. If s contains consecutive spaces, split will produce empty strings,
    // which we will treat as words to be reversed (they will remain empty).
    StringBuilder result = new StringBuilder();
    String[] parts = s.split(" ");
    for (int i = 0; i < parts.length; i++) {
        String word = parts[i];
        // Reverse the word
        String reversed = new StringBuilder(word).reverse().toString();
        result.append(reversed);
        if (i < parts.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int n = s.length();
    StringBuilder result = new StringBuilder(n);
    StringBuilder current = new StringBuilder();
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            // reverse current word
            for (int j = current.length() - 1; j >= 0; j--) {
                result.append(current.charAt(j));
            }
            current.setLength(0);
            // keep the space
            result.append(' ');
        } else {
            current.append(c);
        }
    }
    // append the last word if any
    for (int j = current.length() - 1; j >= 0; j--) {
        result.append(current.charAt(j));
    }
    return result.toString();
}

