            if (Character.isWhitespace(c)) {
                result.append(word.reverse());
                word.setLength(0);
                result.append(c);
            } else {
                word.append(c);
            }
        }
        // Append the last word after the loop
        result.append(word.reverse());
    } catch (RuntimeException e) {
        // In case of any unexpected runtime issue, rethrow as an IllegalArgumentException
        throw new IllegalArgumentException("Error processing input string", e);
    }
    return result.toString();
}
